@RunWith(RobolectricTestRunner.class) @Config(sdk={27,28},application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class LocalFirstBootstrapRuntimeTest {
 public static class OnlineActivity extends PhoneRuntimeTest.OfflineActivity {@Override boolean mapInternetAvailable(){return true;} @Override boolean accountConnected(){return true;}}
 static void le(byte[] b,int at,long v,int count){for(int i=0;i<count;i++)b[at+i]=(byte)(v>>>(8*i));}
 @Test public void downloadedMapIsTheInitialSourceEvenOnlineAndNetworkChangesKeepTheView()throws Exception{org.robolectric.android.controller.ActivityController<OnlineActivity> c=Robolectric.buildActivity(OnlineActivity.class).setup();try{OnlineActivity a=c.get();a.initialLoad.get(30,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();File d=new File(a.getFilesDir(),"pmtiles");d.mkdirs();byte[] h=new byte[127],directory={1,0,1,6,1},tile={26,4,120,2,10,0};System.arraycopy("PMTiles".getBytes("US-ASCII"),0,h,0,7);h[7]=3;le(h,8,127,8);le(h,16,5,8);le(h,56,132,8);le(h,64,6,8);h[97]=1;h[98]=1;h[99]=1;h[101]=14;le(h,102,-100000000,4);le(h,106,400000000,4);le(h,110,200000000,4);le(h,114,650000000,4);try(OutputStream out=new FileOutputStream(new File(d,"bootstrap.pmtiles"))){out.write(h);out.write(directory);out.write(tile);}a.invalidateInstalledMosaic();a.mapConnectionMode="online";a.selected="Carte";a.render();assertTrue("local renderer selected",a.mapLibrePreview);assertFalse(a.forceOnlineMapLibre);JSONObject boot=new JSONObject(a.new MapRadarBridge(a.map).mapBootstrap());assertTrue("bootstrap local",boot.getBoolean("local"));assertTrue("bootstrap online",boot.getBoolean("online"));assertEquals(14,boot.getInt("maxZoom"));a.mapReady=true;WebView map=a.map;a.selectMapConnection("offline");assertSame(map,a.map);a.selectMapConnection("auto");assertSame(map,a.map);a.selectMapPalette("ocean",false);boot=new JSONObject(a.new MapRadarBridge(a.map).mapBootstrap());assertEquals("#72c8f3",boot.getJSONObject("palette").getString("water"));}finally{c.pause().stop().destroy();}}
}
